import os
import re
import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns

# Configuration
# Point this to the specific .txt file generated by your evaluation script
LOG_FILE = r"C:\Users\kokod\Desktop\martin2\jailbreak_log\jailbreak_evaluation_2026-05-19_07-57-53.txt" 
OUTPUT_DIR = r"C:\Users\kokod\Desktop\martin2\jailbreak_graphs"

# Ensure output directory exists
os.makedirs(OUTPUT_DIR, exist_ok=True)

def parse_log_file(filepath):
    print(f"Parsing log file: {filepath}...")
    data = []
    
    current_model = None
    current_character = None
    current_category = None
    
    with open(filepath, 'r', encoding='utf-8') as f:
        for line in f:
            line = line.strip()
            
            # 1. Extract the file path being evaluated
            if line.startswith("Evaluating:"):
                # Example line: Evaluating: gemma-4-E2B-it-Q4_K_M\Elara\JB-COG-01.csv
                # We need to handle both Windows (\) and Unix (/) slashes just in case
                path_str = line.replace("Evaluating:", "").strip()
                parts = path_str.replace('\\', '/').split('/')
                
                if len(parts) >= 3:
                    current_model = parts[0]
                    current_character = parts[1]
                    filename = parts[-1]
                    # Extract the category (e.g., "JB-COG" from "JB-COG-01.csv")
                    current_category = "-".join(filename.split('-')[:2]) 
                continue
            
            # 2. Extract the Verdict
            if line == "RESULT: JAILBROKEN" or line == "RESULT: SECURE":
                if current_model and current_character:
                    data.append({
                        "Model": current_model,
                        # Clean up model name for graphs
                        "Model_Short": current_model.replace('-Instruct', '').replace('-Q4_K_M', '').replace('.Q4_K_S', ''),
                        "Character": current_character,
                        "Category": current_category,
                        "Verdict": "JAILBROKEN" if "JAILBROKEN" in line else "SECURE",
                        "Is_Jailbroken": 1 if "JAILBROKEN" in line else 0
                    })
                # Reset for safety
                current_model, current_character, current_category = None, None, None

    df = pd.DataFrame(data)
    print(f"Successfully parsed {len(df)} evaluation records.")
    return df

def print_summary_statistics(df):
    print("\n" + "="*60)
    print("🚨 JAILBREAK EVALUATION STATISTICS 🚨")
    print("="*60)
    
    total_evals = len(df)
    total_jailbreaks = df['Is_Jailbroken'].sum()
    overall_jsr = (total_jailbreaks / total_evals) * 100 if total_evals > 0 else 0
    
    print(f"\nOverall Jailbreak Success Rate (JSR): {overall_jsr:.2f}% ({total_jailbreaks}/{total_evals})")

    print("\n--- Vulnerability by Model (JSR %) ---")
    model_stats = df.groupby('Model_Short')['Is_Jailbroken'].mean() * 100
    model_stats = model_stats.sort_values(ascending=False)
    for model, jsr in model_stats.items():
        print(f"{model:<30}: {jsr:.2f}%")

    print("\n--- Vulnerability by Character (JSR %) ---")
    char_stats = df.groupby('Character')['Is_Jailbroken'].mean() * 100
    char_stats = char_stats.sort_values(ascending=False)
    for char, jsr in char_stats.items():
        print(f"{char:<30}: {jsr:.2f}%")

    print("\n--- Vulnerability by Attack Category (JSR %) ---")
    cat_stats = df.groupby('Category')['Is_Jailbroken'].mean() * 100
    cat_stats = cat_stats.sort_values(ascending=False)
    for cat, jsr in cat_stats.items():
        print(f"{cat:<30}: {jsr:.2f}%")
        
    print("\n" + "="*60 + "\n")

def plot_jsr_by_model(df):
    plt.figure(figsize=(10, 6))
    sns.set_theme(style="whitegrid")
    
    # Calculate percentages
    model_jsr = df.groupby('Model_Short')['Is_Jailbroken'].mean().sort_values(ascending=False) * 100
    
    ax = sns.barplot(x=model_jsr.values, y=model_jsr.index, palette="flare")
    
    plt.title('Jailbreak Success Rate (JSR) by Model\n(Higher % = More Vulnerable)', fontsize=14, fontweight='bold')
    plt.xlabel('Jailbreak Success Rate (%)', fontsize=12)
    plt.ylabel('Model', fontsize=12)
    plt.xlim(0, 100)
    
    # Add percentage labels to the bars
    for i, v in enumerate(model_jsr.values):
        ax.text(v + 1, i, f"{v:.1f}%", color='black', va='center', fontweight='bold')
        
    plt.tight_layout()
    save_path = os.path.join(OUTPUT_DIR, 'jsr_by_model.png')
    plt.savefig(save_path, dpi=300)
    print(f"Saved graph: {save_path}")
    plt.close()

def plot_jsr_heatmap(df):
    plt.figure(figsize=(12, 8))
    
    # Pivot table: Rows=Models, Cols=Categories, Values=JSR (%)
    pivot_df = df.pivot_table(
        index='Model_Short', 
        columns='Category', 
        values='Is_Jailbroken', 
        aggfunc='mean'
    ) * 100
    
    # Heatmap (Red means highly vulnerable, Green means secure)
    sns.heatmap(
        pivot_df, 
        annot=True, 
        fmt=".1f", 
        cmap="RdYlGn_r", 
        vmin=0, 
        vmax=100, 
        linewidths=.5,
        cbar_kws={'label': 'Jailbreak Success Rate (%)'}
    )
    
    plt.title('Heatmap: Vulnerability by Model and Attack Category', fontsize=14, fontweight='bold')
    plt.xlabel('Attack Category (Prompt Prefix)', fontsize=12)
    plt.ylabel('Model', fontsize=12)
    plt.tight_layout()
    
    save_path = os.path.join(OUTPUT_DIR, 'heatmap_model_vs_category.png')
    plt.savefig(save_path, dpi=300)
    print(f"Saved graph: {save_path}")
    plt.close()

def main():
    # Make sure to update LOG_FILE at the top of the script!
    if not os.path.exists(LOG_FILE):
        print(f"Error: Could not find log file at {LOG_FILE}")
        print("Please update the LOG_FILE variable with the exact timestamped filename.")
        return

    df = parse_log_file(LOG_FILE)
    
    if df.empty:
        print("No valid evaluation data found. Check the log file format.")
        return

    # Print terminal statistics
    print_summary_statistics(df)
    
    # Generate visual graphs
    print("Generating visualizations...")
    plot_jsr_by_model(df)
    plot_jsr_heatmap(df)
    
    print("\nAll done! Check the output directory for your graphs.")

if __name__ == "__main__":
    main()